        color: hsl(var(--vc-text-main));
        font-size: 13px;
        cursor: pointer;
      }
      .sc-filters-count {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        min-width: 1.25rem;
        height: 1.25rem;
        padding: 0 0.35rem;
        border-radius: var(--vc-radius-pill);
        background-color: hsl(var(--vc-accent));
        color: hsl(var(--vc-accent-content));
        font-size: 11px;
      }
      .sc-clear {
        display: inline-flex;
        align-items: center;
        gap: 0.35rem;
        height: 2.15rem;
        padding: 0 0.6rem;
        border-radius: var(--vc-radius-md);
        font-size: 12px;
        color: hsl(var(--vc-error));
        cursor: pointer;
      }
      .sc-clear:hover {
        background-color: hsl(var(--vc-error-soft));
        color: hsl(var(--vc-error-soft-content));
      }

      /* ── The white plane the calendar lives on ──────────────────── */
      .sc-plane {
        background-color: hsl(var(--vc-bg-surface));
        border-radius: var(--vc-radius-lg);
        overflow: hidden;
      }
      .sc-weekdays {
        display: grid;
        grid-template-columns: repeat(7, minmax(0, 1fr));
        padding: 0.6rem 0;
      }
      .sc-weekdays > span {
        text-align: center;
      }

      /* ── Month ──────────────────────────────────────────────────── */
      /* Hairlines only: the grid is drawn by 0.5px rules, never by boxes. */
      .sc-month {
        display: grid;
        grid-template-columns: repeat(7, minmax(0, 1fr));
        border-top: 0.5px solid hsl(var(--vc-border));
      }
      .sc-cell {
        min-height: 7.5rem;
        padding: 0.4rem;
        display: flex;
        flex-direction: column;
        gap: 0.25rem;
        border-bottom: 0.5px solid hsl(var(--vc-border));
        border-right: 0.5px solid hsl(var(--vc-border));
      }
      .sc-cell:nth-child(7n) {
        border-right: none;
      }
      .sc-cell.is-outside {
        background-color: hsl(var(--vc-bg-surface-high) / 0.45);
      }
      .sc-cell.is-outside .sc-daynum {
        color: hsl(var(--vc-text-disabled));
      }
      .sc-cell-head {
        display: flex;
        justify-content: flex-end;
      }
      .sc-daynum {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        min-width: 1.55rem;
        height: 1.55rem;
        padding: 0 0.35rem;
        border-radius: var(--vc-radius-pill);
        font-size: 12px;
        color: hsl(var(--vc-text-muted));
        font-variant-numeric: tabular-nums;
      }
      /* Today = the active state, so it wears lima. */
      .sc-daynum.is-today {
        background-color: hsl(var(--vc-accent));
        color: hsl(var(--vc-accent-content));
        font-weight: 500;
      }
      .sc-cell-body {
        display: flex;
        flex-direction: column;
        gap: 0.2rem;
        min-height: 0;
      }
      .sc-more {
        text-align: left;
        font-size: 11px;
        color: hsl(var(--vc-text-muted));
        padding: 0.1rem 0.3rem;
        cursor: pointer;
        border-radius: var(--vc-radius-sm);
      }
      .sc-more:hover {
        color: hsl(var(--vc-primary));
      }

      /* ── Week ───────────────────────────────────────────────────── */
      .sc-week {
        display: grid;
        grid-template-columns: repeat(7, minmax(0, 1fr));
        border-top: 0.5px solid hsl(var(--vc-border));
        min-height: 22rem;
      }
      .sc-daycol {
        display: flex;
        flex-direction: column;
        gap: 0.4rem;
        padding: 0.6rem 0.5rem;
        border-right: 0.5px solid hsl(var(--vc-border));
      }
      .sc-daycol:last-child {
        border-right: none;
      }
      .sc-daycol-head {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 0.3rem;
      }
      .sc-daycol-body {
        display: flex;
        flex-direction: column;
        gap: 0.35rem;
      }

      /* ── Board ──────────────────────────────────────────────────── */
      .sc-board {
        display: flex;
        align-items: flex-start;
        gap: 0.85rem;
        overflow-x: auto;
        padding-bottom: 0.5rem;
      }
      .sc-col {
        flex: 1 0 15rem;
        max-width: 22rem;
        display: flex;
        flex-direction: column;
        gap: 0.5rem;
        padding: 0.6rem;
        border-radius: var(--vc-radius-lg);
        transition: background-color var(--vc-dur-fast) var(--vc-ease-standard);
      }
      /* The drop target is the ONLY thing that gets a fill: the accent's own
         soft tint, so the column says where it will land in its own colour. */
      .sc-col.is-over {
        background-color: hsl(var(--st-soft));
      }
      .sc-col-head {
        display: flex;
        align-items: center;
        gap: 0.45rem;
        padding: 0 0.25rem;
      }
      .sc-dot {
        width: 0.5rem;
        height: 0.5rem;
        border-radius: var(--vc-radius-full);
        background-color: hsl(var(--st));
        flex-shrink: 0;
      }
      .sc-col-title {
        font-size: 13px;
        font-weight: 500;
      }
      .sc-col-count {
        margin-left: auto;
        font-variant-numeric: tabular-nums;
      }
      .sc-col-body {
        display: flex;
        flex-direction: column;
        gap: 0.4rem;
        min-height: 4rem;
      }
      .sc-col-empty {
        padding: 0.75rem 0.25rem;
      }

      /* ── List ───────────────────────────────────────────────────── */
      .sc-list {
        display: flex;
        flex-direction: column;
        gap: 1.25rem;
      }
      .sc-group-head {
        display: flex;
        align-items: baseline;
        gap: 0.6rem;
        padding: 0 0.25rem 0.5rem;
      }
      .sc-group-title {
        font-size: 15px;
        font-weight: 500;
      }
      .sc-group-body {
        display: flex;
        flex-direction: column;
        gap: 0.35rem;
      }

      /* ── Card ───────────────────────────────────────────────────── */
      /* White plane on the gray, no border, no shadow. The rail is the only
         colour, and it is the status accent. */
      .sc-card {
        position: relative;
        display: flex;
        align-items: stretch;
        gap: 0.5rem;
        padding: 0.4rem 0.55rem 0.4rem 0;
        background-color: hsl(var(--vc-bg-surface));
        border-radius: var(--vc-radius-sm);
        overflow: hidden;
        cursor: pointer;
        transition: background-color var(--vc-dur-fast) var(--vc-ease-standard), opacity var(--vc-dur-fast) var(--vc-ease-standard);
      }
      .sc-card:hover {
        background-color: hsl(var(--vc-bg-surface-high));
      }
      /* In the dark the white plane is nearly the colour of the canvas, so it
         catches a light edge instead — the same trick surface-card uses. */
      :host(.dark) .sc-card {
        box-shadow: inset 0 0.5px 0 hsl(0 0% 100% / 0.07);
      }
      :host(.dark) .sc-card.is-compact {
        box-shadow: none;
      }
      .sc-card:focus-visible {
        outline: none;
        box-shadow: var(--vc-shadow-focus, 0 0 0 2px hsl(var(--vc-focus-ring) / 0.6));
      }
      .sc-card.is-dragging {
        opacity: 0.4;
      }
      /* El REBOTE (2.1): el servidor rechazó el movimiento, la tarjeta volvió
         a su columna y lo dice con una sacudida corta —el aviso trae la razón—.
         El color es el de error, por token, y se apaga solo. */
      .sc-card.is-bounced {
        animation: sc-bounce-back 0.45s ease-in-out;
        box-shadow: 0 0 0 1.5px hsl(var(--vc-error) / 0.7);
      }
      @keyframes sc-bounce-back {
        0%,
        100% {
          transform: translateX(0);
        }
        20% {
          transform: translateX(-5px);
        }
        45% {
          transform: translateX(4px);
        }
        70% {
          transform: translateX(-2px);
        }
      }
      @media (prefers-reduced-motion: reduce) {
        .sc-card.is-bounced {
          animation: none;
        }
      }
      /* VENCIDO (2.3): el estado derivado se dice con una anotación en vino
         (el token de error, nunca lima) y con un riel del mismo color. Es una
         nota al margen, no una alarma: el diseño Seemly informa, no regaña. */
      .sc-card.is-overdue .sc-rail {
        background-color: hsl(var(--vc-error));
      }
      .sc-card-late {
        margin-top: 0.1rem;
        color: hsl(var(--vc-error));
      }
      .sc-card.is-done .sc-card-title {
        color: hsl(var(--vc-text-muted));
        text-decoration: line-through;
        text-decoration-thickness: 0.5px;
      }
      .sc-rail {
        width: 3px;
        flex-shrink: 0;
        border-radius: var(--vc-radius-pill);
        background-color: hsl(var(--st));
      }
      .sc-card-body {
        min-width: 0;
        flex: 1 1 auto;
      }
      .sc-card-title {
        font-size: 13px;
        line-height: 17px;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
      }
      .sc-card-meta {
        margin-top: 0.1rem;
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
      }
      /* Inside a month cell a card is one quiet line. */
      .sc-card.is-compact {
        padding: 0.15rem 0.35rem 0.15rem 0;
        background-color: transparent;
      }
      .sc-card.is-compact:hover {
        background-color: hsl(var(--vc-bg-surface-high));
      }
      .sc-card.is-compact .sc-card-title {
        font-size: 12px;
        line-height: 16px;
      }

      /* ── Empty / loading ────────────────────────────────────────── */
      .sc-empty {
        display: flex;
        flex-direction: column;
        align-items: center;
        justify-content: center;
        gap: 0.75rem;
        padding: 4rem 1rem;
        text-align: center;
      }
      .sc-empty-line {
        font-size: 15px;
      }

      /* ── Phones: a month grid of seven columns is unreadable, so the
           calendar falls to the grouped list. The board keeps its columns
           and scrolls, the way boards do everywhere. ─────────────────── */
      @media (max-width: 640px) {
        .sc-title {
          font-size: 22px;
          line-height: 28px;
        }
        .sc-filter {
          flex-basis: 100%;
        }
        .sc-col {
          flex-basis: 13rem;
        }
      }
